import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import { dbService } from "../services/dbService";
import { WORLD } from "../utils/constants";
import { World } from "../types";
import { loadCurrentWorld, saveCurrentWorld } from "./world/currentWorld";
import { logToTimeline } from "./world/timeline";

// Helper function to handle database errors
const handleDbError = (error: unknown, rejectWithValue: any) => {
  console.error("Database Error:", error);
  if (error instanceof Error) {
    return rejectWithValue(error.message);
  }
  return rejectWithValue("An error occurred while accessing the database.");
};

// Async Thunks
export const fetchWorlds = createAsyncThunk(
  "world/fetchAll",
  async (_, { rejectWithValue }) => {
    try {
      return await dbService.getAllWorlds();
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  }
);

export const fetchWorldById = createAsyncThunk(
  "world/fetchById",
  async (id: number, { rejectWithValue }) => {
    try {
      return await dbService.getWorldById(id);
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  }
);

export const addWorld = createAsyncThunk(
  "world/add",
  async (world: Omit<World, "id">, { rejectWithValue }) => {
    try {
      if (!world.name.trim() || !world.premise.trim()) {
        throw new Error("World name and premise are required.");
      }
      // Every field is kept, like addCharacter, so later additions (a persona,
      // story time) aren't dropped on creation.
      const { id: _ignoredId, ...newWorld } = world as World;
      const created = await dbService.addWorld(newWorld);
      void logToTimeline(created, { kind: "begin", text: `${newWorld.name} began` }, newWorld.storyTime);
      return { id: created, ...newWorld } as World;
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  }
);

export const updateWorld = createAsyncThunk(
  "world/update",
  async (world: World, { rejectWithValue }) => {
    try {
      await dbService.updateWorld(world);
      return world;
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  }
);

// Changes only the named fields of the world as it is now in the database
// (#173). Whole-object saves from a copy read earlier could undo what was
// saved in between - a storyline chapter, an event, a newcomer - when the
// background watcher and you saved close together. `change` can be worked
// out from the latest world.
export const patchWorld = (id: number, change: Partial<World> | ((latest: World) => Partial<World>)) => async (dispatch: (a: any) => any) => {
  const latest = await dbService.getWorldById(id);
  return dispatch(updateWorld({ ...latest, ...(typeof change === "function" ? change(latest) : change), id }));
};

export const deleteWorld = createAsyncThunk(
  "world/delete",
  async (worldId: number, { rejectWithValue }) => {
    try {
      await dbService.clearWorldFromAdventures(worldId);
      await dbService.deleteWorld(worldId);
      return worldId;
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  }
);

interface WorldState {
  worlds: World[];
  currentWorldId: number | null; // the world on screen (#143); null = "My world"
  loading: boolean;
  error: string | null;
}

const initialState: WorldState = {
  worlds: [],
  currentWorldId: loadCurrentWorld(),
  loading: false,
  error: null,
};

const worldSlice = createSlice({
  name: WORLD,
  initialState,
  reducers: {
    switchWorld: (state, action: { payload: number | null }) => {
      state.currentWorldId = action.payload;
      saveCurrentWorld(action.payload);
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchWorlds.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchWorlds.fulfilled, (state, action) => {
        state.loading = false;
        state.worlds = action.payload;
      })
      .addCase(fetchWorlds.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      .addCase(fetchWorldById.fulfilled, (state, action) => {
        const idx = state.worlds.findIndex((w) => w.id === action.payload.id);
        if (idx !== -1) state.worlds[idx] = action.payload;
        else state.worlds.push(action.payload);
      })
      .addCase(fetchWorldById.rejected, (state, action) => {
        state.error = action.payload as string;
      })
      .addCase(addWorld.fulfilled, (state, action) => {
        state.worlds.push(action.payload);
      })
      .addCase(addWorld.rejected, (state, action) => {
        state.error = action.payload as string;
      })
      .addCase(updateWorld.fulfilled, (state, action) => {
        const idx = state.worlds.findIndex((w) => w.id === action.payload.id);
        if (idx !== -1) state.worlds[idx] = action.payload;
      })
      .addCase(updateWorld.rejected, (state, action) => {
        state.error = action.payload as string;
      })
      .addCase(deleteWorld.fulfilled, (state, action) => {
        state.worlds = state.worlds.filter((world) => world.id !== action.payload);
        if (state.currentWorldId === action.payload) {
          state.currentWorldId = null;
          saveCurrentWorld(null);
        }
      })
      .addCase(deleteWorld.rejected, (state, action) => {
        state.error = action.payload as string;
      });
  },
});

export const { switchWorld } = worldSlice.actions;
export default worldSlice.reducer;
